theorem ratEquiv_trans {Z₁ Z₂ Z₃ : CycleGroup X p}
    (h₁₂ : RatEquiv Z₁ Z₂) (h₂₃ : RatEquiv Z₂ Z₃) :
    RatEquiv Z₁ Z₃

theorem ratEquiv_add {Z₁ Z₁' Z₂ Z₂' : CycleGroup X p}
    (h₁ : RatEquiv Z₁ Z₁') (h₂ : RatEquiv Z₂ Z₂') :
    RatEquiv (Z₁ + Z₂) (Z₁' + Z₂')

def pullbackCohom (f : E → E')
    (hf : Differentiable 𝕜 f)
    (h_comm : ∀ η : DiffForm 𝕜 E' F n, Differentiable 𝕜 η →
      ∀ x, d (pullback f η) x = pullback f (d η) x)
    (h_diff_pb : ∀ η : DiffForm 𝕜 E' F n, Differentiable 𝕜 η →
      Differentiable 𝕜 (pullback f η)) :
    @DeRhamCohomology 𝕜 _ E' _ _ F _ _ n →
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n

theorem cohomologous_symm {ω₁ ω₂ : DiffForm 𝕜 E F (n + 1)}
    (h : Cohomologous ω₁ ω₂) :
    Cohomologous ω₂ ω₁

def cohomAdd :
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n →
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n →
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n

def cohomSmul (c : 𝕜) :
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n →
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n

def cohomNeg :
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n →
    @DeRhamCohomology 𝕜 _ E _ _ F _ _ n

def wedgeAlt {p q : ℕ}
    (α : E [⋀^Fin p]→ₗ[ℝ] ℝ) (β : E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    E [⋀^Fin (p + q)]→ₗ[ℝ] ℝ

theorem wedgeAlt_add_left {p q : ℕ}
    (α₁ α₂ : E [⋀^Fin p]→ₗ[ℝ] ℝ) (β : E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    wedgeAlt (α₁ + α₂) β = wedgeAlt α₁ β + wedgeAlt α₂ β

theorem wedgeAlt_add_right {p q : ℕ}
    (α : E [⋀^Fin p]→ₗ[ℝ] ℝ) (β₁ β₂ : E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    wedgeAlt α (β₁ + β₂) = wedgeAlt α β₁ + wedgeAlt α β₂

theorem wedgeAlt_smul_left {p q : ℕ}
    (c : ℝ) (α : E [⋀^Fin p]→ₗ[ℝ] ℝ) (β : E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    wedgeAlt (c • α) β = c • wedgeAlt α β

def wedgeForm {p q : ℕ}
    (α : E → E [⋀^Fin p]→ₗ[ℝ] ℝ) (β : E → E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    E → E [⋀^Fin (p + q)]→ₗ[ℝ] ℝ

theorem wedgeForm_add_left {p q : ℕ}
    (α₁ α₂ : E → E [⋀^Fin p]→ₗ[ℝ] ℝ) (β : E → E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    wedgeForm (α₁ + α₂) β = wedgeForm α₁ β + wedgeForm α₂ β

theorem wedgeForm_add_right {p q : ℕ}
    (α : E → E [⋀^Fin p]→ₗ[ℝ] ℝ) (β₁ β₂ : E → E [⋀^Fin q]→ₗ[ℝ] ℝ) :
    wedgeForm α (β₁ + β₂) = wedgeForm α β₁ + wedgeForm α β₂

def wedgeContinuous {p q : ℕ}
    (α : E [⋀^Fin p]→L[ℝ] ℝ) (β : E [⋀^Fin q]→L[ℝ] ℝ) :
    E [⋀^Fin (p + q)]→L[ℝ] ℝ

def wedgeDiffForm {p q : ℕ}
    (α : DiffForm ℝ E ℝ p) (β : DiffForm ℝ E ℝ q) :
    DiffForm ℝ E ℝ (p + q)

theorem coexact_isCoclosed {k'' : ℕ}
    [cdm2 : CodifferentialMap (E := E) k' k'']
    (h_sq_zero : ∀ (η : DiffForm ℝ E ℝ k), cdm2.codiff (cdm.codiff η) = 0)
    {ω : DiffForm ℝ E ℝ k'}
    (h : IsCoexact (cdm := cdm) ω) :
    IsCoclosed (cdm := cdm2) ω

theorem differentiable_extDeriv_of_contDiff {n : ℕ} {r : WithTop ℕ∞}
    (ω : DiffForm ℝ E ℝ n) (hω : ContDiff ℝ r ω) (hr : minSmoothness ℝ 2 ≤ r) :
    Differentiable ℝ (fun x => extDeriv ω x)

class HarmonicIffClosedCoclosed (k : ℕ)
    [hlm : HodgeLaplacianMap (E := E) k]
    [cdm : CodifferentialMap (E := E) k (k - 1)]

theorem basisFormAlt_zero_of_ne {σ τ : Fin k → Fin n}
    (hne : ∃ j, τ j ∉ Set.range σ) :
    basisFormAlt b σ (b ∘ τ) = 0

theorem basisForm_kronecker (hσ : Function.Injective σ) {τ : Fin k → Fin n}
    (hτ : Function.Injective τ) (hσm : StrictMono σ) (hτm : StrictMono τ) :
    (basisForm b σ) (b ∘ τ) = if σ = τ then 1 else 0
